def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    recent5_d = 0
    recent10_c = 0
    start5 = n - 5
    start10 = n - 10

    for i in range(n):
        o = history[i][1]
        if o == 'C':
            opp_c += 1
            if i >= start10:
                recent10_c += 1
        else:
            if i >= start5:
                recent5_d += 1

    opp_d = n - opp_c

    if n >= 10 and opp_c <= 2:
        return 'D'
    if n >= 30 and opp_c * 5 < n:
        return 'D'

    if opp_last == 'C':
        if my_last == 'C':
            opp_coop_streak = 0
            i = n - 1
            while i >= 0 and history[i][1] == 'C':
                opp_coop_streak += 1
                i -= 1

            if n >= 18 and opp_coop_streak >= 6:
                if opp_d == 0:
                    if rng.random() < 0.12:
                        return 'D'
                elif opp_d * 10 <= n:
                    if rng.random() < 0.08:
                        return 'D'
                elif opp_d * 5 <= n and opp_coop_streak >= 8:
                    if rng.random() < 0.06:
                        return 'D'
                elif opp_d * 4 <= n:
                    if rng.random() < 0.03:
                        return 'D'

            return 'C'

        dc_streak = 0
        i = n - 1
        while i >= 0 and history[i][0] == 'D' and history[i][1] == 'C':
            dc_streak += 1
            i -= 1

        if dc_streak >= 2:
            if opp_d * 5 <= n:
                if rng.random() < 0.9:
                    return 'D'
            elif rng.random() < 0.5:
                return 'D'
            return 'C'

        if opp_d == 0:
            if rng.random() < 0.75:
                return 'D'
            return 'C'

        if opp_d * 4 <= n and recent10_c >= 7:
            if rng.random() < 0.7:
                return 'D'
            return 'C'

        if n >= 2 and history[-2][1] == 'D' and opp_c * 2 >= n:
            if rng.random() < 0.6:
                return 'D'

        opp_coop_streak = 0
        i = n - 1
        while i >= 0 and history[i][1] == 'C':
            opp_coop_streak += 1
            i -= 1

        if opp_coop_streak >= 4 and rng.random() < 0.3:
            return 'D'

        return 'C'

    opp_def_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_def_streak += 1
        i -= 1

    both_def_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D' and history[i][1] == 'D':
        both_def_streak += 1
        i -= 1

    if my_last == 'C':
        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'D':
            if opp_c * 3 >= n * 2:
                if rng.random() < 0.85:
                    return 'C'
            elif opp_c * 2 >= n:
                if rng.random() < 0.5:
                    return 'C'
            elif rng.random() < 0.15:
                return 'C'
            return 'D'

        if opp_def_streak >= 2:
            if opp_c * 10 >= n * 9 and recent10_c >= 8:
                if rng.random() < 0.2:
                    return 'C'
            return 'D'

        if recent5_d <= 1:
            if opp_d * 5 <= n and recent10_c >= 6:
                if rng.random() < 0.8:
                    return 'C'
            elif recent10_c >= 8:
                if rng.random() < 0.5:
                    return 'C'

        return 'D'

    if opp_c * 3 <= n:
        return 'D'
    if opp_c <= 2:
        return 'D'

    if both_def_streak >= 2 or opp_def_streak >= 4:
        if opp_c * 3 >= n * 2:
            if rng.random() < 0.55:
                return 'C'
        elif opp_c * 2 >= n:
            if rng.random() < 0.3:
                return 'C'
        elif rng.random() < 0.08:
            return 'C'
        return 'D'

    if recent10_c >= 5 and rng.random() < 0.12:
        return 'C'

    return 'D'
